const o = require('ospec');
const { toRomaji } = require('../src/romaji');
const {
  H,
  M,
  S,
  T,
  A,
  I,
  U,
  GEMINATE,
  PALATALIZER,
  NON_KANA,
} = require('../src/data');

o.spec('h + u', () => {
  o('H + U is romanized as "hu" by default', () => {
    const actual = toRomaji([H, U], {});
    o(actual).equals('hu');
  });

  o('H + U is romanized as "fu" when config set to anglophone', () => {
    const actual = toRomaji([H, U], { anglophone: true });
    o(actual).equals('fu');
  });
});

o.spec('s + palatal', () => {
  o('S + I is romanized as "si" by default', () => {
    const actual = toRomaji([S, I], {});
    o(actual).equals('si');
  });

  o('S + I is romanized as "shi" when config set to anglophone', () => {
    const actual = toRomaji([S, I], { anglophone: true });
    o(actual).equals('shi');
  });

  o('S + Y is romanized as "sy" by default', () => {
    const actual = toRomaji([S, PALATALIZER, A], {});
    o(actual).equals('sya');
  });

  o('S + Y is romanized as "sh" when config set to anglophone', () => {
    const actual = toRomaji([S, PALATALIZER, A], { anglophone: true });
    o(actual).equals('sha');
  });
});

o.spec('t + palatal', () => {
  o('T + I is romanized as "ti" by default', () => {
    const actual = toRomaji([T, I], {});
    o(actual).equals('ti');
  });

  o('T + I is romanized as "chi" when config set to anglophone', () => {
    const actual = toRomaji([T, I], { anglophone: true });
    o(actual).equals('chi');
  });

  o('T + Y is romanized as "ty" by default', () => {
    const actual = toRomaji([T, PALATALIZER, A], {});
    o(actual).equals('tya');
  });

  o('T + Y is romanized as "ch" when config set to anglophone', () => {
    const actual = toRomaji([T, PALATALIZER, A], { anglophone: true });
    o(actual).equals('cha');
  });

  o('T + U is romanized as "tsu" when config set to anglophone', () => {
    const actual = toRomaji([T, U], { anglophone: true });
    o(actual).equals('tsu');
  });

  o('GEMINATE is romanized as apostrophe at end', () => {
    const actual = toRomaji([M, I, GEMINATE], {});
    o(actual).equals("mi'");
  });

  o('GEMINATE is romanized as apostrophe before other chars', () => {
    const actual = toRomaji([M, I, GEMINATE, NON_KANA('a')], {});
    o(actual).equals("mi'a");
  });
});
